def laravel(routes): return '<?php\nuse Illuminate\\Support\\Facades\\Route;\nuse Illuminate\\Http\\Request;\n'+routes+'\n'
def symfony(methods): return '<?php\nnamespace App\\Controller;\nuse Symfony\\Bundle\\FrameworkBundle\\Controller\\AbstractController;\nuse Symfony\\Component\\HttpFoundation\\Request;\nuse Symfony\\Component\\HttpFoundation\\Response;\nuse Symfony\\Component\\HttpFoundation\\JsonResponse;\nuse Symfony\\Component\\HttpFoundation\\RedirectResponse;\nuse Symfony\\Component\\Routing\\Attribute\\Route;\nclass LessonController extends AbstractController {\n'+methods+'\n}\n'
def rails(routes, methods): return '# config/routes.rb\nRails.application.routes.draw do\n'+routes+'\nend\n\n# app/controllers/lesson_controller.rb\nclass LessonController < ActionController::API\n'+methods+'\nend\n'
course('laravel','Laravel','php','Examples use Laravel 11 or 12 with its supported PHP version.','Create a practice Laravel project with Composer, then replace routes/web.php with one example. Start php artisan serve --host=127.0.0.1 --port=8000. These read-only starter routes need no database.','Laravel is a PHP framework with routing, response helpers and collections. These first lessons work with small web replies.',[
L('first-route','Return a greeting','Route::get connects a URL to a function. Open GET /.',laravel('Route::get("/", fn () => "Hello, Asha!");'),'Hello, Asha!','Change the message.','Use routes/web.php for these unprefixed web routes.'),
L('json','Send JSON data','The response helper can make JSON. Open GET /book.',laravel('Route::get("/book", fn () => response()->json(["title" => "Moon Trip", "pages" => 24]));'),'{"title":"Moon Trip","pages":24}','Add an author field.','Use a JSON response when sending data rather than HTML.'),
L('route-inputs','Read a name in the path','Curly braces mark a route input. Open GET /hello/Ravi.',laravel('Route::get("/hello/{name}", fn (string $name) => response("Hi, " . $name . "!")->header("Content-Type", "text/plain"));'),'Hi, Ravi!','Visit /hello/Asha.','Do not place raw user input in HTML.'),
L('query','Read a query value','Laravel can give the route a Request object. GET /search?q=cat reads the query value.',laravel('Route::get("/search", fn (Request $request) => response()->json(["term" => $request->query("q", "")]));'),'{"term":"cat"}','Leave out q.','Query inputs should be checked before important use.'),
L('constraints','Limit a route input','whereNumber only matches numeric path text. Open GET /double/4.',laravel('Route::get("/double/{n}", fn (string $n) => response()->json(["answer" => (int) $n * 2]))->whereNumber("n");'),'{"answer":8}','Visit /double/cat.','A route rule checks matching; it does not set every business limit.'),
L('named-routes','Build a URL from a name','name gives a route a reusable label. GET /link builds a relative URL to that named route.',laravel('Route::get("/hello/{name}", fn (string $name) => $name)->name("hello");\nRoute::get("/link", fn () => route("hello", ["name" => "Asha"], false));'),'/hello/Asha','Change the route path and observe the generated link.','The route input key must match the placeholder name.'),
L('redirects','Send a client to another page','redirect makes an HTTP redirect. A browser following GET /start reaches /hello.',laravel('Route::get("/start", fn () => redirect("/hello"));\nRoute::get("/hello", fn () => "Welcome");'),'Welcome','Inspect the first response Location header.','A redirect tells the client to make a new request.'),
L('not-found','Report a missing item','A JSON response can include an error status. Open GET /missing.',laravel('Route::get("/missing", fn () => response()->json(["error" => "Book not found"], 404));'),'{"error":"Book not found"}','Inspect the 404 status too.','An error message should use an appropriate error status.'),
L('headers','Set a cache rule','The header method adds response metadata. GET /note has a no-store rule.',laravel('Route::get("/note", fn () => response("Practice note")->header("Cache-Control", "no-store"));'),'Practice note','Inspect Cache-Control with curl -i.','A header is separate from the response body.'),
L('collections','Filter a collection','A collection wraps values with useful methods. GET /scores filters scores and resets their numeric keys.',laravel('Route::get("/scores", fn () => response()->json(collect([4, 8, 9])->filter(fn ($n) => $n >= 7)->values()->all()));'),'[8,9]','Raise the limit to 9.','values resets keys so this result remains a JSON array.'),
L('mapping','Transform a collection','map makes a new value for every collection item. Open GET /double.',laravel('Route::get("/double", fn () => response()->json(collect([2, 3])->map(fn ($n) => $n * 2)->all()));'),'[4,6]','Multiply by 3.','map transforms values; filter chooses which values remain.'),
L('route-groups','Share a path prefix','A route group can share a prefix. Open GET /api/books.',laravel('Route::prefix("api")->group(function () {\n Route::get("books", fn () => response()->json(["Moon Trip"]));\n});'),'["Moon Trip"]','Add a pets route inside the group.','In this web.php example the api prefix is added explicitly.')])
course('symfony','Symfony','php','Examples use Symfony 7 with PHP 8.2 or later.','Create a Symfony 7 skeleton project with Composer and install the Symfony CLI. Save each example as src/Controller/LessonController.php. Use the default attribute route import. Run symfony server:start --no-tls --port=8000.','Symfony is a PHP framework built from reusable components. These lessons use its routes, requests and response objects.',[
L('first-route','Make a controller route','A Route attribute maps a URL to a controller method. Open GET /hello.',symfony('#[Route("/hello", methods: ["GET"])]\npublic function hello(): Response { return new Response("Hello, Asha!"); }'),'Hello, Asha!','Change the greeting.','Keep the attribute above the method it describes.'),
L('json','Return JSON data','JsonResponse turns an array into JSON and sets its content type. Open GET /book.',symfony('#[Route("/book", methods: ["GET"])]\npublic function book(): JsonResponse { return new JsonResponse(["title" => "Moon Trip", "pages" => 24]); }'),'{"title":"Moon Trip","pages":24}','Add an author field.','Use JsonResponse rather than hand-building JSON strings.'),
L('route-inputs','Read a route value','A route placeholder can become a method input. Open GET /hello/Ravi.',symfony('#[Route("/hello/{name}", methods: ["GET"])]\npublic function hello(string $name): Response { return new Response("Hi, " . $name . "!", 200, ["Content-Type" => "text/plain"]); }'),'Hi, Ravi!','Visit /hello/Asha.','Treat route inputs as untrusted text.'),
L('query','Read query data','A Request object gives access to query values. Open GET /search?q=cat.',symfony('#[Route("/search", methods: ["GET"])]\npublic function search(Request $request): JsonResponse { return new JsonResponse(["term" => $request->query->get("q", "")]); }'),'{"term":"cat"}','Leave out q.','Check client values before using them in a database query or file path.'),
L('constraints','Constrain a path number','A route requirement describes allowed path text. Open GET /double/4.',symfony('#[Route("/double/{n}", requirements: ["n" => "[0-9]+"], methods: ["GET"])]\npublic function twice(int $n): JsonResponse { return new JsonResponse(["answer" => $n * 2]); }'),'{"answer":8}','Visit /double/cat.','A requirement controls route matching, not every allowed data range.'),
L('json-body','Read a JSON body','Request::toArray reads JSON into an array. Send POST /books with application/json and {"title":"Moon Trip"}.',symfony('#[Route("/books", methods: ["POST"])]\npublic function create(Request $request): JsonResponse {\n $data = $request->toArray();\n if (!is_string($data["title"] ?? null)) return new JsonResponse(["error" => "Title needed"], 400);\n return new JsonResponse(["title" => $data["title"]], 201);\n}'),'{"title":"Moon Trip"}','Send an empty object.','Malformed JSON can fail before your own field checks run.'),
L('named-routes','Generate a named URL','A route name lets code build a link without repeating its path. Open GET /link.',symfony('#[Route("/hello/{name}", name: "hello", methods: ["GET"])]\npublic function hello(string $name): Response { return new Response($name); }\n#[Route("/link", methods: ["GET"])]\npublic function link(): Response { return new Response($this->generateUrl("hello", ["name" => "Asha"])); }'),'/hello/Asha','Change the route path and compare the link.','The parameter key must match the placeholder.'),
L('redirects','Return a redirect','RedirectResponse tells a client where to request next. GET /start ends at /hello in a browser.',symfony('#[Route("/start", methods: ["GET"])]\npublic function start(): RedirectResponse { return new RedirectResponse("/hello"); }\n#[Route("/hello", methods: ["GET"])]\npublic function hello(): Response { return new Response("Welcome"); }'),'Welcome','Inspect the first Location header.','A redirect starts a new client request.'),
L('not-found','Send an error status','The second JsonResponse argument is the status. Open GET /missing.',symfony('#[Route("/missing", methods: ["GET"])]\npublic function missing(): JsonResponse { return new JsonResponse(["error" => "Book not found"], 404); }'),'{"error":"Book not found"}','Inspect the 404 status.','Do not hide a missing item behind a 200 success status.'),
L('headers','Add reply metadata','A Response has a header bag. Open GET /note and inspect Cache-Control.',symfony('#[Route("/note", methods: ["GET"])]\npublic function note(): Response { $response = new Response("Practice note"); $response->headers->set("Cache-Control", "no-store"); return $response; }'),'Practice note','Add a simple X-Lesson header.','Headers and body are separate parts of a response.'),
L('methods','Restrict an HTTP method','The methods option limits which requests match. GET /ready gives this reply; POST is not allowed.',symfony('#[Route("/ready", methods: ["GET"])]\npublic function ready(): Response { return new Response("Ready"); }'),'Ready','Send POST and inspect 405.','Use the correct HTTP method for the operation.'),
L('lists','Send a list of values','A PHP list becomes a JSON array. Open GET /books.',symfony('#[Route("/books", methods: ["GET"])]\npublic function books(): JsonResponse { return new JsonResponse(["Moon Trip", "Sun Trip"]); }'),'["Moon Trip","Sun Trip"]','Add another book.','A JSON list has ordered items; an object has named fields.')])
course('ruby-on-rails','Ruby on Rails','ruby','Examples use Rails 7.1 or later in API-only mode with a supported Ruby version.','Create a practice project with rails new school --api --skip-active-record. Enter it. Put each labelled section into its named file, then run bin/rails server -b 127.0.0.1 -p 8000. No database is needed.','Rails is a Ruby framework with clear places for routes and controllers. These API-only examples return small data replies.',[
L('first-action','Make a controller action','A route names a controller and action. GET /hello runs LessonController#hello.',rails('get "/hello", to: "lesson#hello"','def hello\n render plain: "Hello, Asha!"\nend'),'Hello, Asha!','Change the greeting.','The file lesson_controller.rb must define LessonController.'),
L('json','Render JSON data','render json turns a Ruby value into a JSON response. Open GET /book.',rails('get "/book", to: "lesson#book"','def book\n render json: { title: "Moon Trip", pages: 24 }\nend'),'{"title":"Moon Trip","pages":24}','Add an author field.','Do not call render twice in one action.'),
L('path-inputs','Read a path input','A colon marks a route value. GET /hello/Ravi places Ravi in params[:name].',rails('get "/hello/:name", to: "lesson#hello"','def hello\n render plain: "Hi, #{params[:name]}!"\nend'),'Hi, Ravi!','Visit /hello/Asha.','Use plain text or safe templates when returning user text.'),
L('query-inputs','Read query data','params also contains query values. Open GET /search?q=cat.',rails('get "/search", to: "lesson#search"','def search\n render json: { term: params[:q] || "" }\nend'),'{"term":"cat"}','Leave out q.','Client parameters need checks before important use.'),
L('post-body','Read a JSON request','Send POST /books with application/json and {"title":"Moon Trip"}. Rails puts body values in params.',rails('post "/books", to: "lesson#create"','def create\n if !params[:title].is_a?(String)\n  render json: { error: "Title needed" }, status: :bad_request\n  return\n end\n render json: { title: params[:title] }, status: :created\nend'),'{"title":"Moon Trip"}','Send an empty object.','This example returns data but does not save a database record.'),
L('strong-parameters','Choose allowed inputs','permit chooses allowed parameter keys. Send POST /books with title and an extra secret key; only title is returned.',rails('post "/books", to: "lesson#create"','def create\n allowed = params.permit(:title)\n render json: allowed\nend'),'{"title":"Moon Trip"}','Add another permitted field deliberately.','Permitting a key does not validate its meaning or value.'),
L('status','Report a missing item','Rails status symbols name HTTP statuses. Open GET /missing.',rails('get "/missing", to: "lesson#missing"','def missing\n render json: { error: "Book not found" }, status: :not_found\nend'),'{"error":"Book not found"}','Inspect status 404.','An error body should come with an error status.'),
L('named-routes','Build a path from a route helper','The as option names a route helper. Open GET /link to see the helper fill in a name.',rails('get "/hello/:name", to: "lesson#hello", as: :hello\nget "/link", to: "lesson#link"','def hello\n render plain: params[:name]\nend\ndef link\n render plain: hello_path(name: "Asha")\nend'),'/hello/Asha','Change the name passed to hello_path.','Path helper inputs must match the route values.'),
L('redirects','Redirect a client','redirect_to sends a Location header. A browser following GET /start reaches /hello.',rails('get "/start", to: "lesson#start"\nget "/hello", to: "lesson#hello"','def start\n redirect_to "/hello"\nend\ndef hello\n render plain: "Welcome"\nend'),'Welcome','Inspect the first 302 response.','Return after a redirect if more code should not run.'),
L('headers','Set response metadata','response.headers holds reply headers. Open GET /note.',rails('get "/note", to: "lesson#note"','def note\n response.headers["Cache-Control"] = "no-store"\n render plain: "Practice note"\nend'),'Practice note','Inspect the cache header.','Set headers before the response is completed.'),
L('callbacks','Run a shared step','before_action runs before controller actions. GET /school reads the value set by the callback.',rails('get "/school", to: "lesson#school"','before_action :set_school\ndef school\n render plain: @school\nend\nprivate\ndef set_school\n @school = "Oak School"\nend'),'Oak School','Change the school name.','Callbacks can affect many actions, so keep their purpose clear.'),
L('no-content','Return an empty successful reply','head sends a status and no body. DELETE /books/1 returns 204 in this practice-only action.',rails('delete "/books/:id", to: "lesson#destroy"','def destroy\n head :no_content\nend'),'204 No Content; empty body','Inspect the response with an HTTP client.','This sample has no stored records; it demonstrates the response shape only.')])
